package cli

import (
	"context"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/spf13/cobra"
)

// onDemandPluginInstall shares the normal install workflow, including index
// overrides, name/checksum validation and dependency confirmation. Tests replace
// it to exercise the prompt and dispatch without downloading real releases.
var onDemandPluginInstall = runRemoteInstall

func installMissingPlugin(ctx context.Context, rootCmd *cobra.Command, name string) (string, error) {
	// The plugin may already be in the managed directory and merely
	// unreachable through PATH: a local-dev symlink whose target moved, or a
	// managed bin dir that could not be prepended at startup. Offering to
	// install over it is a dead end — installRepoAtTag refuses an existing
	// install without --force, so the user answers Yes, waits for three
	// network round-trips and gets "already installed; use --force to
	// replace". Execute the managed entry instead, which is what this
	// function's own return contract promises below.
	//
	// A listing error falls through to the install rather than failing here:
	// the install path reads the same directory and reports the problem in
	// terms of what it was trying to do.
	if installed, err := FindInstalledPlugin(name); err == nil && installed != nil {
		return installed.Path, nil
	}
	if !interactive.CanPromptInteractively() {
		return "", fmt.Errorf("the entire-%s plugin is not installed; run 'entire plugin install %s' and retry", name, name)
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}
	confirmed, err := runPluginConfirm(ctx, rootCmd.ErrOrStderr(), fmt.Sprintf("Install the entire-%s plugin?", name), true)
	if err != nil {
		if ctx.Err() != nil {
			return "", err
		}
		return "", handleFormCancellation(rootCmd.ErrOrStderr(), "Install", err)
	}
	if !confirmed {
		fmt.Fprintln(rootCmd.ErrOrStderr(), "Install cancelled.")
		return "", nil
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}

	// Keep install progress off stdout: the original command may emit JSON or
	// be piped to another tool. Do not parse any of the plugin's arguments.
	cmd := newPluginInstallCmd()
	cmd.SetOut(rootCmd.ErrOrStderr())
	cmd.SetErr(rootCmd.ErrOrStderr())
	if err := onDemandPluginInstall(ctx, cmd, installSource{Kind: installFromIndex, Ref: name}, remoteInstallFlags{}); err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}
	installed, err := FindInstalledPlugin(name)
	if err != nil {
		return "", err
	}
	if installed == nil {
		return "", fmt.Errorf("the entire-%s plugin was not installed; run 'entire plugin install %s' and retry", name, name)
	}
	// Execute the managed entry directly, even if the managed directory could
	// not be prepended to PATH at startup.
	return installed.Path, nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sync"

	tea "charm.land/bubbletea/v2"
	"charm.land/huh/v2"
	"github.com/muesli/cancelreader"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
)

// pluginPromptTerminal is the controlling terminal a confirmation prompt uses.
//
// in is the terminal rather than os.Stdin, so a confirmation never consumes
// bytes the plugin was piped. out is the terminal's own output handle, used
// only when the writer the caller supplied is not itself a terminal — see
// runPluginConfirm. It is nil when there is nothing to fall back to, which is
// the case in tests that replace the opener.
type pluginPromptTerminal struct {
	in  io.ReadCloser
	out io.Writer
	// closeOut releases out when it is a handle of its own. Unix hands back
	// one file for both directions, so closing in covers it there; Windows
	// opens CONIN$ and CONOUT$ separately, and writing to CONIN$ renders
	// nothing — which is why the pair cannot be collapsed to one handle.
	closeOut func()
}

// Tests replace the opener rather than redirecting the command's data stream.
var openPluginPromptTerminal = func() (pluginPromptTerminal, error) {
	in, out, err := tea.OpenTTY()
	if err != nil {
		return pluginPromptTerminal{}, fmt.Errorf("open confirmation terminal: %w", err)
	}
	t := pluginPromptTerminal{in: in, out: out}
	if out != in {
		t.closeOut = func() { _ = out.Close() }
	}
	return t, nil
}

func runPluginConfirm(ctx context.Context, out io.Writer, prompt string, defaultYes bool) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, fmt.Errorf("confirmation cancelled: %w", err)
	}
	term, err := openPluginPromptTerminal()
	if err != nil {
		return false, err
	}
	input := term.in
	closeInput := sync.OnceFunc(func() { _ = input.Close() })
	defer closeInput()
	if term.closeOut != nil {
		defer term.closeOut()
	}
	// The answer is read from the terminal, so the question has to be visible
	// there. A supplied writer that is not a terminal — `entire graph 2>log`,
	// or any wrapper capturing stderr — left the prompt invisible while the
	// terminal sat in raw mode waiting for a keypress, and with Yes as the
	// default an idle Enter authorized a download-and-exec nobody was shown.
	// Render on the terminal the answer comes from instead; the escape
	// sequences had no business in the redirect either way.
	render := out
	if term.out != nil && !interactive.IsTerminalWriter(out) {
		render = term.out
	}
	answer := defaultYes
	form := NewAccessibleForm(huh.NewGroup(huh.NewConfirm().Title(prompt).Value(&answer))).WithOutput(render).WithInput(input)
	if IsAccessibleMode() {
		// Huh's accessible scanner ignores context and treats EOF as the default.
		// Make the read cancellable and retain EOF so it cannot authorize an install.
		reader, readErr := cancelreader.NewReader(input)
		if readErr != nil {
			return false, fmt.Errorf("confirmation input: %w", readErr)
		}
		defer reader.Close()
		cancelled := make(chan struct{})
		stop := context.AfterFunc(ctx, func() {
			if !reader.Cancel() {
				// Some platforms cannot cancel reads on a separately opened
				// terminal. This descriptor belongs to the prompt, so closing
				// it is safe and also releases a blocked read.
				closeInput()
			}
			close(cancelled)
		})
		defer func() {
			if !stop() {
				<-cancelled
			}
		}()
		checked := &pluginConfirmReader{Reader: reader}
		err = form.WithInput(checked).RunWithContext(ctx)
		if ctx.Err() != nil {
			return false, fmt.Errorf("confirmation cancelled: %w", ctx.Err())
		}
		if checked.err != nil {
			if errors.Is(checked.err, io.EOF) {
				return false, nil
			}
			return false, fmt.Errorf("confirmation input: %w", checked.err)
		}
	} else {
		err = form.RunWithContext(ctx)
	}
	if ctx.Err() != nil {
		return false, fmt.Errorf("confirmation cancelled: %w", ctx.Err())
	}
	if err != nil {
		return false, fmt.Errorf("confirmation form: %w", err)
	}
	return answer, nil
}

type pluginConfirmReader struct {
	io.Reader

	err error
}

func (r *pluginConfirmReader) Read(p []byte) (int, error) {
	n, err := r.Reader.Read(p)
	if n == 0 {
		r.err = err
	}
	return n, err //nolint:wrapcheck // preserve io.Reader EOF semantics for the scanner
}

package cli

import (
	"context"
	"fmt"
	"io"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
)

type pluginProgressKey struct{}

// withPluginProgress opts the command into progress reporting. The context
// carries the writer through dependency installs without making library callers
// print to the process's terminal.
func withPluginProgress(ctx context.Context, out io.Writer) context.Context {
	return context.WithValue(ctx, pluginProgressKey{}, out)
}

// startPluginStep reports work before it starts. Stop the spinner before any
// prompt, warning or result is printed. The returned stop is idempotent so a
// deferred cleanup can also cover early returns.
func startPluginStep(ctx context.Context, message string) func() {
	out, ok := ctx.Value(pluginProgressKey{}).(io.Writer)
	if !ok {
		return func() {}
	}
	if IsAccessibleMode() || !interactive.ShouldStyle(out) {
		fmt.Fprintln(out, message)
		return func() {}
	}
	stop := startSpinner(out, message)
	var once sync.Once
	return func() { once.Do(func() { stop(false) }) }
}

